/**
 * Web 用户端 mock 认证：企业邮箱登录、忘记密码、会话门禁。
 */
(function (global) {
  var AUTH_KEY = 'proto_user_auth';
  var CRED_KEY = 'proto_user_auth_credentials';
  var REMEMBER_KEY = 'proto_user_auth_remember';

  var ENTERPRISE_DOMAINS = ['cnooc.com.cn', 'cnooc.com', 'haineng.com.cn'];

  var DEFAULT_USER = {
    email: 'zhangsan@cnooc.com.cn',
    password: 'Aq123456',
    userName: '张三',
    userId: 'user_zhang',
    orgName: '海能集团',
    departmentName: '平台团队',
    roleLabel: '普通用户',
    avatarText: '张'
  };

  function readJson(key, fallback) {
    try {
      var raw = localStorage.getItem(key) || sessionStorage.getItem(key);
      if (raw) return JSON.parse(raw);
    } catch (e) {}
    return fallback;
  }

  function writeJson(key, value, persistent) {
    try {
      var store = persistent ? localStorage : sessionStorage;
      store.setItem(key, JSON.stringify(value));
    } catch (e) {}
  }

  function removeJson(key) {
    try {
      localStorage.removeItem(key);
      sessionStorage.removeItem(key);
    } catch (e) {}
  }

  function seedCredentials() {
    if (readJson(CRED_KEY, null)) return;
    writeJson(CRED_KEY, {
      email: DEFAULT_USER.email,
      password: DEFAULT_USER.password
    }, true);
  }

  function isEnterpriseEmail(email) {
    var value = String(email || '').trim().toLowerCase();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) return false;
    var domain = value.split('@')[1];
    return ENTERPRISE_DOMAINS.some(function (d) {
      return domain === d || domain.endsWith('.' + d);
    });
  }

  function currentPath() {
    try {
      return global.location.pathname.split('/').pop() || 'index.html';
    } catch (e) {
      return 'index.html';
    }
  }

  function isPublicPage() {
    var page = currentPath();
    return page === 'login.html' || page === 'forgot-password.html';
  }

  function redirectToLogin() {
    if (isPublicPage()) return;
    var redirect = encodeURIComponent(global.location.pathname.split('/').slice(-2).join('/') + global.location.search + global.location.hash);
    global.location.href = 'login.html?redirect=' + redirect;
  }

  function syncPortalContext(session) {
    if (!global.UserPortalContext || !session) return;
    UserPortalContext.set({
      userId: session.userId,
      userName: session.userName,
      orgName: session.orgName,
      departmentName: session.departmentName,
      roleLabel: session.roleLabel,
      avatarText: session.avatarText,
      email: session.email
    });
    if (global.UserPersonalSpace && typeof UserPersonalSpace.updateProfileFromAuth === 'function') {
      UserPersonalSpace.updateProfileFromAuth(session);
    }
  }

  function getSession() {
    var remember = localStorage.getItem(REMEMBER_KEY) === '1';
    return readJson(AUTH_KEY, null) || (remember ? null : null);
  }

  function readSession() {
    if (sessionStorage.getItem(AUTH_KEY)) return readJson(AUTH_KEY, null);
    if (localStorage.getItem(REMEMBER_KEY) === '1' && localStorage.getItem(AUTH_KEY)) {
      return readJson(AUTH_KEY, null);
    }
    return null;
  }

  function saveSession(session, remember) {
    removeJson(AUTH_KEY);
    writeJson(AUTH_KEY, session, !!remember);
    if (remember) localStorage.setItem(REMEMBER_KEY, '1');
    else localStorage.removeItem(REMEMBER_KEY);
    syncPortalContext(session);
  }

  function login(email, password, remember) {
    seedCredentials();
    var cred = readJson(CRED_KEY, { email: DEFAULT_USER.email, password: DEFAULT_USER.password });
    var normalized = String(email || '').trim().toLowerCase();
    if (!isEnterpriseEmail(normalized)) {
      return { ok: false, error: '请使用企业邮箱登录（如 @cnooc.com.cn）' };
    }
    if (normalized !== cred.email || String(password || '') !== cred.password) {
      return { ok: false, error: '邮箱或密码错误' };
    }
    var session = {
      email: normalized,
      userId: DEFAULT_USER.userId,
      userName: DEFAULT_USER.userName,
      orgName: DEFAULT_USER.orgName,
      departmentName: DEFAULT_USER.departmentName,
      roleLabel: DEFAULT_USER.roleLabel,
      avatarText: DEFAULT_USER.avatarText,
      loggedInAt: Date.now()
    };
    saveSession(session, remember);
    return { ok: true, session: session };
  }

  function logout() {
    removeJson(AUTH_KEY);
    localStorage.removeItem(REMEMBER_KEY);
    global.location.href = 'login.html';
  }

  function changePassword(currentPassword, newPassword, confirmPassword) {
    seedCredentials();
    var cred = readJson(CRED_KEY, { email: DEFAULT_USER.email, password: DEFAULT_USER.password });
    if (String(currentPassword || '') !== cred.password) {
      return { ok: false, error: '原密码不正确' };
    }
    if (!newPassword || newPassword.length < 8) {
      return { ok: false, error: '新密码至少 8 位' };
    }
    if (newPassword !== confirmPassword) {
      return { ok: false, error: '两次输入的新密码不一致' };
    }
    writeJson(CRED_KEY, { email: cred.email, password: newPassword }, true);
    return { ok: true };
  }

  function resetPassword(email, code, newPassword, confirmPassword) {
    if (!isEnterpriseEmail(email)) return { ok: false, error: '邮箱格式不正确' };
    if (String(code || '').trim() !== '123456') return { ok: false, error: '验证码错误（原型 mock：123456）' };
    if (!newPassword || newPassword.length < 8) return { ok: false, error: '新密码至少 8 位' };
    if (newPassword !== confirmPassword) return { ok: false, error: '两次输入的新密码不一致' };
    seedCredentials();
    var cred = readJson(CRED_KEY, { email: DEFAULT_USER.email, password: DEFAULT_USER.password });
    cred.email = String(email).trim().toLowerCase();
    cred.password = newPassword;
    writeJson(CRED_KEY, cred, true);
    return { ok: true };
  }

  function requireAuth() {
    seedCredentials();
    if (isPublicPage()) return readSession();
    if (!readSession()) {
      redirectToLogin();
      return null;
    }
    return readSession();
  }

  function mountUserBadge(el) {
    var session = readSession();
    if (!el || !session) return;
    el.textContent = session.email || session.userName;
  }

  global.UserAuth = {
    login: login,
    logout: logout,
    changePassword: changePassword,
    resetPassword: resetPassword,
    requireAuth: requireAuth,
    getSession: readSession,
    isEnterpriseEmail: isEnterpriseEmail,
    mountUserBadge: mountUserBadge,
    DEFAULT_USER: DEFAULT_USER,
    MOCK_RESET_CODE: '123456'
  };

  if (typeof document !== 'undefined' && document.currentScript && !isPublicPage()) {
    requireAuth();
  }
})(window);

