/* --- Web 用户端 v4：认证 / 图表 / 笔记 popover / 轮播箭头 --- */

.aioq-auth-page {
  min-height: 100vh;
  background: linear-gradient(160deg, #eef4ff 0%, #f8fafc 45%, #fff 100%);
}

.aioq-auth-shell {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.aioq-auth-card {
  width: min(420px, 100%);
  background: #fff;
  border: 1px solid #e3e9f0;
  border-radius: 12px;
  padding: 28px 28px 24px;
  box-shadow: 0 12px 40px rgba(15, 43, 73, 0.08);
}

.aioq-auth-brand {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
}

.aioq-auth-card h1 {
  margin: 0 0 8px;
  font-size: 22px;
  color: #1a2535;
}

.aioq-auth-hint {
  margin: 0 0 20px;
  font-size: 13px;
  color: #64748b;
  line-height: 1.5;
}

.aioq-auth-form label {
  display: block;
  margin-bottom: 14px;
}

.aioq-auth-form label span,
.aioq-auth-field span {
  display: block;
  margin-bottom: 6px;
  font-size: 13px;
  color: #475569;
}

.aioq-auth-form input,
.aioq-auth-field input {
  width: 100%;
  box-sizing: border-box;
  border: 1px solid #d7e0ea;
  border-radius: 8px;
  padding: 10px 12px;
  font-size: 14px;
}

.aioq-auth-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
  font-size: 13px;
}

.aioq-auth-check {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: #475569;
}

.aioq-auth-error {
  margin: 0 0 12px;
  color: #b42318;
  font-size: 13px;
}

.aioq-auth-submit {
  width: 100%;
}

.aioq-auth-foot {
  margin-top: 16px;
  text-align: center;
  font-size: 13px;
}

.aioq-space-link-btn {
  border: 0;
  background: transparent;
  color: #0a4db8;
  cursor: pointer;
  font-size: 14px;
  padding: 0;
}

.aioq-space-tech-item--action {
  align-items: center;
}

.aioq-top-link--btn {
  border: 0;
  background: transparent;
  cursor: pointer;
  font: inherit;
}

.aioq-composer-context-status {
  margin: 6px 4px 0;
  font-size: 12px;
  color: #64748b;
}

.aioq-context-token--note {
  cursor: pointer;
}

.aioq-note-ref-popover {
  position: fixed;
  z-index: 60;
  max-width: 320px;
  background: #fff;
  border: 1px solid #e3e9f0;
  border-radius: 10px;
  box-shadow: 0 12px 32px rgba(15, 43, 73, 0.12);
  padding: 12px 14px;
}

.aioq-note-ref-popover strong {
  display: block;
  margin-bottom: 6px;
  color: #1a2535;
}

.aioq-note-ref-popover p {
  margin: 0;
  font-size: 13px;
  color: #475569;
  line-height: 1.5;
}

.aioq-answer-chart {
  margin-top: 12px;
  padding: 12px;
  border: 1px solid #e3e9f0;
  border-radius: 10px;
  background: #f8fbff;
}

.aioq-answer-chart-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
  font-size: 13px;
  color: #64748b;
}

.aioq-answer-chart-head strong {
  color: #1a2535;
}

.aioq-answer-chart-svg {
  width: 100%;
  height: auto;
  display: block;
}

.aioq-square-banner-wrap {
  position: relative;
}

.aioq-banner-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 2;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.35);
  background: rgba(255, 255, 255, 0.15);
  color: #fff;
  font-size: 22px;
  line-height: 1;
  cursor: pointer;
}

.aioq-banner-nav--prev { left: 12px; }
.aioq-banner-nav--next { right: 12px; }

.aioq-banner-nav:hover {
  background: rgba(255, 255, 255, 0.28);
}

